sp_instance.widget_parameters:
{
	"html": {
		"value": "<style>
  .cp-hero {
    --cp-navy: #0A2540;
    --cp-gold: #C5A065;
    --cp-teal: #14B8A6;
    --cp-white: #F7F9FC;
    --cp-line: #DDE5EE;
    --cp-muted: #5E6D7E;
    font-family: "Aptos", "Segoe UI", sans-serif;
    background: var(--cp-white);
    color: var(--cp-navy);
    border-bottom: 1px solid var(--cp-line);
  }

  .cp-hero__wrap {
    max-width: 1120px;
    margin: 0 auto;
    padding: 54px 28px 42px;
  }

  .cp-brand {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 34px;
  }

  .cp-brand__mark {
    width: 54px;
    height: 54px;
    object-fit: contain;
  }

  .cp-brand__name {
    margin: 0;
    font-size: 18px;
    line-height: 1.2;
    font-weight: 850;
    color: var(--cp-navy);
  }

  .cp-brand__tag {
    margin-top: 3px;
    color: var(--cp-muted);
    font-size: 13px;
  }

  .cp-hero__grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 44px;
    align-items: end;
  }

  .cp-eyebrow {
    margin-bottom: 13px;
    color: var(--cp-gold);
    font-size: 12px;
    font-weight: 850;
    letter-spacing: .11em;
    text-transform: uppercase;
  }

  .cp-title {
    max-width: 760px;
    margin: 0;
    color: var(--cp-navy);
    font-size: clamp(34px, 4.6vw, 58px);
    line-height: 1.02;
    font-weight: 900;
    letter-spacing: 0;
  }

  .cp-copy {
    max-width: 650px;
    margin: 18px 0 0;
    color: var(--cp-muted);
    font-size: 17px;
    line-height: 1.62;
  }

  .cp-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 28px;
  }

  .cp-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    padding: 0 18px;
    border-radius: 5px;
    font-size: 14px;
    font-weight: 800;
    text-decoration: none;
    transition: background .16s ease, border-color .16s ease, transform .16s ease;
  }

  .cp-btn:hover,
  .cp-btn:focus {
    transform: translateY(-1px);
    text-decoration: none;
  }

  .cp-btn--primary {
    background: var(--cp-navy);
    border: 1px solid var(--cp-navy);
    color: #fff;
  }

  .cp-btn--primary:hover,
  .cp-btn--primary:focus {
    background: #071A2E;
    color: #fff;
  }

  .cp-btn--secondary {
    background: transparent;
    border: 1px solid var(--cp-line);
    color: var(--cp-navy);
  }

  .cp-btn--secondary:hover,
  .cp-btn--secondary:focus {
    border-color: var(--cp-gold);
    color: var(--cp-navy);
  }

  .cp-side-note {
    border-left: 3px solid var(--cp-gold);
    padding-left: 18px;
    color: var(--cp-muted);
    font-size: 14px;
    line-height: 1.55;
  }

  .cp-side-note strong {
    display: block;
    margin-bottom: 6px;
    color: var(--cp-navy);
    font-size: 15px;
  }

  .cp-status {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 38px;
    padding-top: 18px;
    border-top: 1px solid var(--cp-line);
  }

  .cp-status span {
    display: inline-flex;
    align-items: center;
    min-height: 30px;
    padding: 0 11px;
    border-radius: 999px;
    background: #fff;
    border: 1px solid var(--cp-line);
    color: var(--cp-muted);
    font-size: 12px;
    font-weight: 750;
  }

  .cp-status span:first-child {
    border-color: rgba(20, 184, 166, .45);
    color: #08796F;
  }

  @media (max-width: 820px) {
    .cp-hero__wrap {
      padding: 34px 18px 30px;
    }

    .cp-brand {
      margin-bottom: 26px;
    }

    .cp-hero__grid {
      grid-template-columns: 1fr;
      gap: 26px;
    }

    .cp-side-note {
      max-width: 520px;
    }

    .cp-btn {
      width: 100%;
    }
  }
</style>
<section class="cp-hero" aria-label="Claim Pilot portal hero">
<div class="cp-hero__wrap">
<div class="cp-brand"><img class="cp-brand__mark" src="/x_1970973_claim_0.claim-pilot-logo-only.png" alt="Claim Pilot logo">
<div>
<h2 class="cp-brand__name">Claim Pilot</h2>
<div class="cp-brand__tag">Insurance Claim Portal</div>
</div>
</div>
<div class="cp-hero__grid">
<div>
<div class="cp-eyebrow">Claim intake and tracking</div>
<h1 class="cp-title">Submit your claim.<br>Track every step.</h1>
<p class="cp-copy">File car, medical, and property claims through one secure portal, then follow progress from review to resolution.</p>
<div class="cp-actions"><a class="cp-btn cp-btn--primary" href="?id=sc_cat_item&amp;sys_id=18a0bcf7c30147d0b68cd50d05013103">Submit a Claim</a> <a class="cp-btn cp-btn--secondary" href="?id=claim_pilot_my_claims">View My Claims</a></div>
</div>
<div class="cp-side-note"><strong>Built for clear claim handling.</strong> Upload documents, confirm claim details, and keep the claim team aligned through structured review, tasks, approvals, and SLAs.</div>
</div>
</div>
</section>",
